// Flappy Bird — single-file build
// Generated by combining models.dart, persistence_service.dart,
// sound_manager.dart, painter.dart, game_screen.dart, and main.dart
// into one file, per request. See PUBSPEC_CHANGES.md for required
// dependencies and asset files.

