// ----------------------- DIFFICULTY -----------------------

enum Difficulty { easy, normal, hard }

class DifficultySettings {
  final double gravity;
  final double flapVelocity;
  final double pipeSpeed;
  final double gapHeight;

  const DifficultySettings({
    required this.gravity,
    required this.flapVelocity,
    required this.pipeSpeed,
    required this.gapHeight,
  });

  static const easy = DifficultySettings(
    gravity: 1200,
    flapVelocity: -380,
    pipeSpeed: 150,
    gapHeight: 240,
  );

  static const normal = DifficultySettings(
    gravity: 1400,
    flapVelocity: -420,
    pipeSpeed: 180,
    gapHeight: 200,
  );

  static const hard = DifficultySettings(
    gravity: 1600,
    flapVelocity: -460,
    pipeSpeed: 220,
    gapHeight: 165,
  );

  static DifficultySettings forMode(Difficulty d) {
    switch (d) {
      case Difficulty.easy:
        return easy;
      case Difficulty.normal:
        return normal;
      case Difficulty.hard:
        return hard;
    }
  }

  static String label(Difficulty d) {
    switch (d) {
      case Difficulty.easy:
        return 'Easy';
      case Difficulty.normal:
        return 'Normal';
      case Difficulty.hard:
        return 'Hard';
    }
  }
}

// ----------------------- POWER-UPS -----------------------

enum PowerUpType { shield, slowMo, magnet }

// ----------------------- PIPES -----------------------

/// A vertical gap the bird can safely pass through.
class GapZone {
  final double top;
  final double bottom;
  const GapZone(this.top, this.bottom);
}

class Pipe {
  double x; // left edge
  double gapCenter;
  double gapHeight;
  final double baseGapCenter;

  // Moving-pipe support: gapCenter drifts sinusoidally around baseGapCenter.
  final bool moving;
  final double driftRange;
  final double driftSpeed;
  double driftPhase;

  // Double-gap pipe support: a second, independent opening.
  final bool isDouble;
  double? secondGapCenter;
  double? secondGapHeight;

  bool scored = false;

  final bool hasPowerUp;
  final PowerUpType? powerUpType;
  bool powerUpCollected = false;

  // Which custom picture (if any) this specific pipe was randomly assigned
  // at spawn time — lets pillars vary in appearance instead of all using
  // the same texture. Null falls back to the solid pipe-theme color.
  final ui.Image? pipeImage;

  Pipe({
    required this.x,
    required this.gapCenter,
    required this.gapHeight,
    this.moving = false,
    this.driftRange = 0,
    this.driftSpeed = 0,
    this.isDouble = false,
    this.secondGapCenter,
    this.secondGapHeight,
    this.hasPowerUp = false,
    this.powerUpType,
    this.pipeImage,
  })  : baseGapCenter = gapCenter,
        driftPhase = 0;

  /// The safe (passable) vertical zones for this pipe, sorted top-to-bottom.
  List<GapZone> gapZones() {
    final zones = <GapZone>[
      GapZone(gapCenter - gapHeight / 2, gapCenter + gapHeight / 2),
    ];
    if (isDouble && secondGapCenter != null && secondGapHeight != null) {
      zones.add(GapZone(
        secondGapCenter! - secondGapHeight! / 2,
        secondGapCenter! + secondGapHeight! / 2,
      ));
    }
    zones.sort((a, b) => a.top.compareTo(b.top));
    return zones;
  }
}

// ----------------------- COINS -----------------------

class Coin {
  double x;
  double y;
  bool collected = false;
  Coin({required this.x, required this.y});
}

// ----------------------- PARTICLES -----------------------

class Particle {
  double x, y, vx, vy;
  double life;
  final double maxLife;
  final int colorValue;
  Particle({
    required this.x,
    required this.y,
    required this.vx,
    required this.vy,
    required this.life,
    required this.colorValue,
  }) : maxLife = life;
}

