// ----------------------- LEADERBOARD -----------------------

class LeaderboardEntry {
  final String name;
  final int score;
  const LeaderboardEntry(this.name, this.score);

  Map<String, dynamic> toJson() => {'name': name, 'score': score};
  factory LeaderboardEntry.fromJson(Map<String, dynamic> json) =>
      LeaderboardEntry(json['name'] as String? ?? 'Player', json['score'] as int? ?? 0);
}

// ----------------------- COLLISION HELPER -----------------------

/// Circle-vs-rectangle overlap test (fairer near pipe corners than a plain
/// rect-vs-rect check). Finds the closest point on [rect] to [center] and
/// compares the distance against [radius].
bool circleIntersectsRect(double cx, double cy, double radius, double left,
    double top, double right, double bottom) {
  final closestX = cx.clamp(left, right);
  final closestY = cy.clamp(top, bottom);
  final dx = cx - closestX;
  final dy = cy - closestY;
  return (dx * dx + dy * dy) < (radius * radius);
}

double distanceBetween(double x1, double y1, double x2, double y2) {
  final dx = x1 - x2;
  final dy = y1 - y2;
  return sqrt(dx * dx + dy * dy);
}

