/// Wraps shared_preferences so all of the game's persistent state (high
/// score, leaderboard, currency, unlocked cosmetics/achievements, and
/// settings) survives app restarts. Call [init] once before reading
/// anything from it.
class PersistenceService {
  static const _kHighScore = 'flappy_high_score';
  static const _kLeaderboard = 'flappy_leaderboard_v1';
  static const _kTotalCoins = 'flappy_total_coins';
  static const _kUnlockedSkins = 'flappy_unlocked_skins';
  static const _kSelectedSkin = 'flappy_selected_skin';
  static const _kUnlockedPipeThemes = 'flappy_unlocked_pipe_themes';
  static const _kSelectedPipeTheme = 'flappy_selected_pipe_theme';
  static const _kAchievements = 'flappy_achievements';
  static const _kDifficulty = 'flappy_difficulty';
  static const _kMuted = 'flappy_muted';
  static const _kVolume = 'flappy_volume';
  static const _kGamesPlayed = 'flappy_games_played';
  static const _kPlayerName = 'flappy_player_name';

  SharedPreferences? _prefs;

  Future<void> init() async {
    _prefs = await SharedPreferences.getInstance();
  }

  SharedPreferences get _p {
    final prefs = _prefs;
    if (prefs == null) {
      throw StateError('PersistenceService.init() must complete before use');
    }
    return prefs;
  }

  int get highScore => _p.getInt(_kHighScore) ?? 0;
  Future<void> setHighScore(int v) => _p.setInt(_kHighScore, v);

  int get totalCoins => _p.getInt(_kTotalCoins) ?? 0;
  Future<void> setTotalCoins(int v) => _p.setInt(_kTotalCoins, v);

  int get gamesPlayed => _p.getInt(_kGamesPlayed) ?? 0;
  Future<void> setGamesPlayed(int v) => _p.setInt(_kGamesPlayed, v);

  String get playerName => _p.getString(_kPlayerName) ?? 'Player';
  Future<void> setPlayerName(String v) => _p.setString(_kPlayerName, v);

  Difficulty get difficulty {
    final s = _p.getString(_kDifficulty);
    return Difficulty.values.firstWhere(
      (d) => d.name == s,
      orElse: () => Difficulty.normal,
    );
  }

  Future<void> setDifficulty(Difficulty d) => _p.setString(_kDifficulty, d.name);

  bool get muted => _p.getBool(_kMuted) ?? false;
  Future<void> setMuted(bool v) => _p.setBool(_kMuted, v);

  double get volume => _p.getDouble(_kVolume) ?? 0.8;
  Future<void> setVolume(double v) => _p.setDouble(_kVolume, v);

  String get selectedSkin => _p.getString(_kSelectedSkin) ?? 'classic';
  Future<void> setSelectedSkin(String v) => _p.setString(_kSelectedSkin, v);

  List<String> get unlockedSkins =>
      _p.getStringList(_kUnlockedSkins) ?? ['classic'];
  Future<void> setUnlockedSkins(List<String> v) =>
      _p.setStringList(_kUnlockedSkins, v);

  String get selectedPipeTheme => _p.getString(_kSelectedPipeTheme) ?? 'green';
  Future<void> setSelectedPipeTheme(String v) =>
      _p.setString(_kSelectedPipeTheme, v);

  List<String> get unlockedPipeThemes =>
      _p.getStringList(_kUnlockedPipeThemes) ?? ['green'];
  Future<void> setUnlockedPipeThemes(List<String> v) =>
      _p.setStringList(_kUnlockedPipeThemes, v);

  List<String> get unlockedAchievements =>
      _p.getStringList(_kAchievements) ?? [];
  Future<void> setUnlockedAchievements(List<String> v) =>
      _p.setStringList(_kAchievements, v);

  List<LeaderboardEntry> get leaderboard {
    final raw = _p.getString(_kLeaderboard);
    if (raw == null) return [];
    try {
      final list = jsonDecode(raw) as List<dynamic>;
      return list
          .map((e) => LeaderboardEntry.fromJson(e as Map<String, dynamic>))
          .toList();
    } catch (_) {
      return [];
    }
  }

  Future<void> setLeaderboard(List<LeaderboardEntry> entries) {
    final raw = jsonEncode(entries.map((e) => e.toJson()).toList());
    return _p.setString(_kLeaderboard, raw);
  }
}

